 "content": "def transform(grid):
    """Repeat the non-background motif across same-sized regions separated by solid lines."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # A separator is a full, solid row or column, excluding the dominant background.
    sep_rows = [r for r, row in enumerate(grid)
                if len(set(row)) == 1 and row[0] != bg]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def intervals(n, separators):
        out, start = [], 0
        for p in separators:
            if p > start:
                out.append((start, p))
            start = p + 1
        if start < n:
            out.append((start, n))
        return out

    rows = intervals(h, sep_rows)
    cols = intervals(w, sep_cols)
    if len(rows) * len(cols) <= 1:
        return [row[:] for row in grid]

    # Locate the region with the most non-background cells; it is the motif template.
    best = None
    best_count = -1
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            count = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            if count > best_count:
                best_count, best = count, (ri, ci)
    if best_count <= 0:
        return [row[:] for row in grid]

    sri, sci = best
    sr0, sr1 = rows[sri]
    sc0, sc1 = cols[sci]
    rh, cw = sr1 - sr0, sc1 - sc0
    out = [row[:] for row in grid]
    for r0, r1 in rows:
        for c0, c1 in cols:
            if r1 - r0 != rh or c1 - c0 != cw:
                continue
            if (r0, c0) == (sr0, sc0):
                continue
            # Fill empty regions with the template, retaining non-background input cells.
            if all(grid[r][c] == bg for r in range(r0, r1) for c in range(c0, c1)):
                for dr in range(rh):
                    for dc in range(cw):
                        out[r0 + dr][c0 + dc] = grid[sr0 + dr][sc0 + dc]
    return out
